def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]

    # The signal colors are the non-background colors with the fewest cells.
    freq = {c: n for c, n in counts.items() if c != background}
    if not freq:
        return [row[:] for row in grid]
    least = min(freq.values())
    signals = {c for c, n in freq.items() if n <= least + 2}

    points = {c: [] for c in signals}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in signals:
                points[grid[r][c]].append((r, c))

    out = [row[:] for row in grid]
    for color, pts in points.items():
        for i, (r, c) in enumerate(pts):
            for rr, cc in pts[i + 1:]:
                if r == rr:
                    for x in range(min(c, cc) + 1, max(c, cc)):
                        if out[r][x] == 0:
                            out[r][x] = color
                elif c == cc:
                    for y in range(min(r, rr) + 1, max(r, rr)):
                        if out[y][c] == 0:
                            out[y][c] = color
    return out
